/*
All credit to Flockaroo https://www.dwitter.net/u/flockaroo
I came across his implementation, and tried to understand how it worked. It uses some fractal-like
deformation applied to a periodic range, but changing the parameters alters drastically the output,
so I tried to not change the core of the function and added some variation. 
 */
// see: https://github.com/epibyte/p5-epi-shapesvg
const { Point, Line, Polygon } = EpiShapeSvg; // external library https://cdn.jsdelivr.net/gh/epibyte/p5-epi-shapesvg@v0.0.8/dist/p5-epi-shapesvg.js
let svgPolygon;
let PENS = ["navy", "darkgreen"];

let darkColors = ["#03045e", "#023e8a", "#124559", "#0077b6", "#0096c7"];
let lightColors = ["#48cae4", "#90e0ef", "#ade8f4", "#caf0f8", "#EEEEFF"];
let bgColors = ['#fdf0d5', '#fcf6bd', '#d0f4de', '#ffccd5'];

let bgColor, borderColor, sep, numLayers;



function setup() {
  createCanvas(1200, 600);
  noFill();
  regenerateScene();
}

function draw() {
  background(212);
  // fill(bgColor);
  noStroke();
  rect(0, 0, width, height);

  curveTightness(0.75);

  let W = width + 100;
  let resolution = 1;
  let steps = 8000;
	let wNum = 0;

	let polys = [];
	let pts = [];

  for (let k = 0; k < numLayers; k++) {
    let offsetT = k * 0.15;
    let palette = k % 2 === 1 ? darkColors : lightColors;
    let colorIndex = floor(map(noise(wNum * 0.5, k * 0.5), 0, 1, 0, palette.length));
    let fillColor = color(palette[colorIndex]);
    fillColor.setAlpha(50 + 20 * k);

    fill(fillColor);
    stroke(palette[colorIndex]);
    strokeWeight(0.5 + 0.1 * k);
		noFill(); stroke("rgba(233,233,255,0.5)"); strokeWeight(1);
		stroke(PENS[k%PENS.length]);

    beginShape();
    let previousJ = -1;
    let isNewLine = true;

    for (let _step = 0; _step <= steps; _step += resolution) {
      let T = _step / W / 3;
      T = T / sep + offsetT;

      let _j = (_step % W);
      let j = W / 4 + _j;

      let X = j;
      let Y = 0;
      let timeFalloff = 1 - T / 5;
      let waveSize = 5 / timeFalloff;

      if (_j < previousJ) {
        // Close previous wave
        vertex(width + 200, Y + waveSize + 5000 / j - height / 4);
        vertex(width + 200, height + 200);
        vertex(-200, height + 200);
				pts.push({x: width + 200, y: Y + waveSize + 5000 / j - height / 4});
				pts.push({x: width + 200, y: height + 200});
				pts.push({x: -200, y: height + 200});
				polys.push(pts);
        endShape(CLOSE); // CLOSE

        beginShape();
				pts = [];
        isNewLine = true;
        wNum++;
      }

      previousJ = _j;

      while (waveSize < W / 5 / timeFalloff) {
        let A = ((X / waveSize + T + frameCount * 0.05) % 1) * waveSize - waveSize / 2;
        let deform = 1 - ((A * A) / (waveSize * waveSize)) * 4;
        let C = cos(deform);
        let S = sin(deform);

        X += A * C + Y * S - A - 20;
        Y = Y * C - A * S;

        waveSize /= 0.6;
      }

      let finalY = Y + waveSize + 5000 / j - height / 4;

      if (isNewLine) {
        vertex(-200, finalY); // vertex(-200, finalY);
        vertex(X - W / 7, finalY);
				pts.push({x: -200, y: finalY});
				pts.push({x: X - W / 7, y: finalY});
        isNewLine = false;
      } else {
        // curveVertex(X - W / 7, finalY);
				vertex(X - W / 7, finalY);
				pts.push({x: X - W / 7, y: finalY});
      }
    }

		polys.push(pts);
    endShape();
  }
	// if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) console.log(polys);

  // Draw border
  noFill();
  stroke(borderColor);
  strokeWeight(10);
  // rect(0, 0, width, height);

	svgPolygon = new Polygon();
	for (const arr of polys) {
		const ptsArr = arr.map(obj => new Point(obj.x, obj.y));
		svgPolygon.addPtsArr(ptsArr);
	}
	// // noLoop() removed for animation
}

function doubleClicked() { // mousePressed()
  regenerateScene();
  redraw();
}

function mousePressed() {
	if (isLooping()) {
		// noLoop() removed for animation
	} else {
		loop();
	}
}

function keyPressed() {
	if (key === "s") {
		console.log("save svg");
		// const boundary = new Polygon([new Point(0, 0), new Point(width, 0), new Point(width, height), new Point(0, height)], true);
		const boundary = Polygon.createArc(new Point(width/2, height/2), new Point(max(width, height), max(width, height)), 0, TAU);
		const clippedSVG = svgPolygon.clipTo(boundary);
		// console.log(boundary.toSVG());

		let svgAll = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;
		svgAll += `<g stroke="black" fill="none">\n${clippedSVG.toSVG()}</g>\n`;
		svgAll += `</svg>`;
		save(svgAll.split("\n"), "epi_waves.svg.txt");

	}
}

function regenerateScene() {
  bgColor = random(bgColors);
  borderColor = random(darkColors);
  sep = random(0.5, 0.8);
	numLayers = random([2, 3, 4])
}
